// Script to embed TTF fonts as base64 into a TypeScript module
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const boldBuf = fs.readFileSync(path.join(root, 'fonts', 'PlusJakartaSans-Bold.ttf'));
const regularBuf = fs.readFileSync(path.join(root, 'fonts', 'PlusJakartaSans-Regular.ttf'));

const boldB64 = boldBuf.toString('base64');
const regularB64 = regularBuf.toString('base64');

const content = [
  '// Auto-generated by scripts/embed-fonts.cjs — do not edit manually',
  '// Plus Jakarta Sans fonts embedded as base64 for serverless environments (Vercel)',
  '// Source: fontsource/plus-jakarta-sans (SIL Open Font License)',
  '',
  'export const PLUS_JAKARTA_SANS_BOLD_B64 = "' + boldB64 + '";',
  '',
  'export const PLUS_JAKARTA_SANS_REGULAR_B64 = "' + regularB64 + '";',
  '',
].join('\n');

const outPath = path.join(root, 'src', 'lib', 'fonts.ts');
fs.writeFileSync(outPath, content, 'utf8');
console.log('Wrote', outPath, '(' + content.length + ' bytes)');

